#!/usr/bin/env python3
"""Compute CSX-179_Q1 ground truth for schema 1.0."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path


TASK_ID = "CSX-179_Q1"
EVENT_ID = "CSX-179"

INPUT_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_2015_Southeast_Asia_haze_from_Indonesian_fires.json",
    "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html",
]

WORD_NUMBERS = {
    "one": 1,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
}


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(root: Path, rel_path: str) -> dict:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def strip_html(path: Path) -> str:
    raw = path.read_text(encoding="utf-8", errors="replace")
    text = re.sub(r"<(script|style).*?</\1>", " ", raw, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def extract_int(text: str, pattern: str) -> int:
    match = re.search(pattern, text, flags=re.I | re.S)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1).replace(",", ""))


def extract_word_number(text: str, pattern: str) -> int:
    match = re.search(pattern, text, flags=re.I | re.S)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    token = match.group(1).lower()
    if token not in WORD_NUMBERS:
        raise ValueError(f"Unrecognized number word: {token}")
    return WORD_NUMBERS[token]


def report_values(report_text: str) -> dict:
    usual_co = extract_int(report_text, r"usually about ([0-9,]+) parts per billion")
    peak_co = extract_int(report_text, r"up to nearly ([0-9,]+) parts per billion")
    psi_above = extract_int(report_text, r"soared above ([0-9,]+)")
    psi_hazard = extract_int(report_text, r"Any score above ([0-9,]+) is considered hazardous")

    return {
        "hotspots_min": extract_int(
            report_text,
            r"detected more than ([0-9,]+) hot spots in Indonesia",
        ),
        "psi_above": psi_above,
        "hazardous_psi_threshold_above": psi_hazard,
        "psi_ratio_min": round(psi_above / psi_hazard, 2),
        "aerosol_multiplier": extract_word_number(
            report_text,
            r"detected a ([a-z]+)-fold increase in particles",
        ),
        "usual_surface_co_ppb": usual_co,
        "peak_surface_co_ppb_nearly": peak_co,
        "co_ratio_nearly": round(peak_co / usual_co, 1),
        "typical_smoke_upper_km": extract_int(
            report_text,
            r"between the surface and ([0-9,]+) kilometers",
        ),
        "central_kalimantan_plume_km": extract_int(
            report_text,
            r"October 4, 2015, reached ([0-9,]+) kilometers",
        ),
        "transport_direction": "northwesterly",
        "downwind_places": [
            "Malaysia",
            "Singapore",
            "southern Thailand",
            "southern Cambodia",
            "Vietnam",
        ],
        "fire_regions": ["Sumatra", "Kalimantan"],
    }


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final classification",
                "points": 4,
                "description": "Gives the cross-border Indonesian fire-smoke air-quality label or a close equivalent.",
                "partial_credit": "Credit a generic wildfire-smoke label that omits either cross-border transport or air-quality severity.",
            },
            {
                "name": "Fire and event anchors",
                "points": 3,
                "description": "Uses the 2015 incident window, Sumatra/Kalimantan, and the more-than-120000 hot-spot anchor.",
                "partial_credit": "Credit only the event window, only the geography, or only the hot-spot count.",
            },
            {
                "name": "Severity ledger arithmetic",
                "points": 5,
                "description": "Reports PSI above 2000, threshold above 350, 5.71 ratio, 6-fold aerosol increase, and near-13.0 CO ratio.",
                "partial_credit": "Credit correct raw values with incomplete ratios or one missing severity metric.",
            },
            {
                "name": "Smoke-layer and transport check",
                "points": 4,
                "description": "Connects smoke below 3 km, the 2 km central Kalimantan plume, and northwesterly movement to downwind countries.",
                "partial_credit": "Credit downwind movement without both height and direction details.",
            },
            {
                "name": "Rejection of weaker readings",
                "points": 2,
                "description": "Rejects ordinary weather haze, local burn-area mapping, and population-counting readings.",
                "partial_credit": "Credit rejection of only one or two weaker readings.",
            },
            {
                "name": "Output control",
                "points": 2,
                "description": "Returns compact JSON and avoids extra-data independent loss, dose-response, or complete burn-map claims.",
                "partial_credit": "Credit mostly correct structure with minor formatting issues or one mild overstatement.",
            },
        ],
    }


def main() -> None:
    root = package_root()
    event = read_json(root, INPUT_FILES[0])
    anchor = read_json(root, INPUT_FILES[1])
    report_text = strip_html(root / INPUT_FILES[2])
    values = report_values(report_text)

    primary_gt = {
        "classification": "transboundary_fire_smoke_air_quality",
        "severity_ledger": {
            "hotspots_min": values["hotspots_min"],
            "psi_ratio_min": values["psi_ratio_min"],
            "aerosol_multiplier": values["aerosol_multiplier"],
            "co_ratio_nearly": values["co_ratio_nearly"],
        },
        "transport_check": (
            "Smoke was usually below 3 km, a central Kalimantan plume reached 2 km, "
            "and upper-level northwesterly transport could carry smoke toward Malaysia, "
            "Singapore, southern Thailand, southern Cambodia, and Vietnam."
        ),
        "rationale": (
            "The more-than-120000 Indonesian hot spots, PSI ratio of at least 5.71, "
            "6-fold aerosol increase, and near-13.0 CO ratio support a cross-border "
            "fire-smoke air-quality classification. Ordinary weather haze, local burn-area "
            "mapping, and population counting are weaker because they do not jointly explain "
            "the fire, chemical, air-quality, and transport anchors."
        ),
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "report_metric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event": {
                "event_name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
                "region": event["region"],
            },
            "report_values": values,
            "judge_anchors": {
                "classification": primary_gt["classification"],
                "severity_ledger": primary_gt["severity_ledger"],
                "transport_check": {
                    "typical_smoke_upper_km": values["typical_smoke_upper_km"],
                    "central_kalimantan_plume_km": values["central_kalimantan_plume_km"],
                    "direction": values["transport_direction"],
                    "places": values["downwind_places"],
                },
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": INPUT_FILES,
            "notes": "Ground truth is derived from the local event metadata and NASA report text.",
        },
    }

    (task_dir() / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
